/*
 * test_icon_theme.c — headless icon-theme engine suite
 *
 * Pins src/theme/icon_theme.c (the freedesktop icon-theme engine)
 * against a synthetic, fully-controlled fixture tree: a theme with
 * an inheritance chain, a threshold directory, scale!=1 entries,
 * SVG decoys, a pixmaps fallback, and deliberately-missing names.
 * Every fixture icon is a SOLID-COLOR PNG (tests/test_icon_pngs.h,
 * generated by the Python snippet below) so assertions can check
 * not just that a path resolved but WHICH icon a surface decoded —
 * color is identity.
 *
 * Fixture regeneration (Python 3, Pillow not required — plain
 * zlib/struct):
 *
 *   import struct, zlib
 *   def png(w, h, rgb):
 *       raw = b''.join(b'\x00' + bytes([*rgb, 255]) * w for _ in range(h))
 *       def ch(tag, data):
 *           c = struct.pack('>I', len(data)) + tag + data
 *           return c + struct.pack('>I', zlib.crc32(tag + data) & 0xffffffff)
 *       ihdr = struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)
 *       return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', ihdr) + \
 *              ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
 *
 * Covered, group by group:
 *
 *   name detection  — env override > icon-theme file > gtk ini >
 *                     kdeglobals > hicolor; hostile names rejected
 *   lookup          — exact size, inheritance, hicolor terminal,
 *                     relaxed closest-size, scale!=1 skipped,
 *                     SVG never offered, pixmaps last resort
 *   caching         — positive + negative hits, reset drops both
 *   surfaces        — decode + borrow + symbolic tint (pixel proof)
 *   classification  — extension table (case-insensitive), the
 *                     executable-bit stat for extension-less files,
 *                     the place chains
 *
 * Runs headless (no display) — the GUI pixel proof lives in the X11
 * integration suite's file-dialog group.
 */

#include "fdk/fdk.h"
#include "core/alloc_internal.h"
#include "theme/theme_internal.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#ifndef _DEFAULT_SOURCE
#define _DEFAULT_SOURCE
#endif
#include <unistd.h>

#include "test_icon_pngs.h"

static int failures = 0;

#define CHECK(cond, name)                                                  \
    do {                                                                   \
        if (!(cond)) {                                                     \
            fprintf(stderr, "FAIL: %s (line %d)\n", name, __LINE__);       \
            failures++;                                                    \
        }                                                                  \
    } while (0)

/* ---- fixture scaffolding -------------------------------------------- */

static char g_root[512]; /* the scratch root, removed on exit */

static void write_file(const char *path, const void *data, size_t len) {
    FILE *f = fopen(path, "wb");
    if (f == NULL) {
        perror(path);
        exit(2);
    }
    if (len > 0 && fwrite(data, 1, len, f) != len) {
        perror("fwrite");
        exit(2);
    }
    fclose(f);
}

static void mkdir_p(const char *path) {
    if (mkdir(path, 0755) == 0 || errno == EEXIST) {
        return;
    }
    /* Create parents, then retry. */
    char buf[600];
    snprintf(buf, sizeof(buf), "%s", path);
    for (char *slash = buf + 1; *slash != '\0'; slash++) {
        if (*slash == '/') {
            *slash = '\0';
            (void)mkdir(buf, 0755);
            *slash = '/';
        }
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        perror(path);
        exit(2);
    }
}

static void fixture_dir(const char *rel) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    mkdir_p(buf);
}

static void fixture_png(const char *rel, const unsigned char *data,
                        size_t len) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    write_file(buf, data, len);
}

static void fixture_text(const char *rel, const char *content) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/%s", g_root, rel);
    write_file(buf, content, strlen(content));
}

/* Point the engine's whole world at the fixture tree: XDG_DATA_HOME
 * carries the icons, XDG_CONFIG_HOME carries the settings files, and
 * every other discovery input is scrubbed. */
static void env_point_at_fixture(void) {
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/data", g_root);
    setenv("XDG_DATA_HOME", buf, 1);
    snprintf(buf, sizeof(buf), "%s/config", g_root);
    setenv("XDG_CONFIG_HOME", buf, 1);
    snprintf(buf, sizeof(buf), "%s/datadirs", g_root);
    setenv("XDG_DATA_DIRS", buf, 1);
    unsetenv("FDK_ICON_THEME");
    unsetenv("XDG_ICON_THEME");
    fdk__icon_theme_reset();
}

/* Builds:
 *
 *   <root>/data/icons/
 *     fdktest/            (Inherits=fdkparent)
 *       index.theme
 *       16x16/   Fixed 16   folder, text-x-generic, image-x-generic,
 *                            run-symbolic
 *       48x48/   Fixed 48   folder, image-x-generic
 *       32x32/   Scalable 16..64  audio-x-generic
 *       64x64@2/ Fixed 64 Scale=2  video-x-generic   (must be skipped)
 *       24x24/   Threshold 24       archive.png (only .svg decoy in
 *                                    the fixture for 'application-zip')
 *     fdkparent/          (Inherits=hicolor)
 *       index.theme
 *       48x48/   Fixed 48   package-x-generic
 *     hicolor/
 *       index.theme        (no Inherits — the terminal)
 *       16x16/   Fixed 16   text-x-generic   (the inherited last hit)
 *   <root>/config/         (empty until a detection test fills it)
 */
static void build_fixture(void) {
    static char tmpl[] = "/tmp/fdk-itheme-XXXXXX";
    char *d = mkdtemp(tmpl);
    if (d == NULL) {
        perror("mkdtemp");
        exit(2);
    }
    snprintf(g_root, sizeof(g_root), "%s", d);

    fixture_dir("data/icons/fdktest/16x16");
    fixture_dir("data/icons/fdktest/24x24");
    fixture_dir("data/icons/fdktest/32x32");
    fixture_dir("data/icons/fdktest/48x48");
    fixture_dir("data/icons/fdktest/64x64@2");
    fixture_dir("data/icons/fdkparent/48x48");
    fixture_dir("data/icons/hicolor/16x16");
    fixture_dir("config");
    fixture_dir("datadirs/pixmaps");

    fixture_text("data/icons/fdktest/index.theme",
                 "[Icon Theme]\n"
                 "Name=FDK Test\n"
                 "Inherits=fdkparent\n"
                 "Directories=16x16,24x24,32x32,48x48,64x64@2\n"
                 "\n"
                 "[16x16]\nSize=16\nType=Fixed\n"
                 "\n"
                 "[24x24]\nSize=24\nType=Threshold\nThreshold=2\n"
                 "\n"
                 "[32x32]\nSize=32\nType=Scalable\nMinSize=16\n"
                 "MaxSize=64\n"
                 "\n"
                 "[48x48]\nSize=48\nType=Fixed\n"
                 "\n"
                 "[64x64@2]\nSize=64\nType=Fixed\nScale=2\n");

    fixture_text("data/icons/fdkparent/index.theme",
                 "[Icon Theme]\n"
                 "Name=FDK Parent\n"
                 "Inherits=hicolor\n"
                 "Directories=48x48\n"
                 "\n"
                 "[48x48]\nSize=48\nType=Fixed\n");

    fixture_text("data/icons/hicolor/index.theme",
                 "[Icon Theme]\n"
                 "Name=Hicolor\n"
                 "Directories=16x16\n"
                 "\n"
                 "[16x16]\nSize=16\nType=Fixed\n");

    /* The theme's own 16-px set. */
    fixture_png("data/icons/fdktest/16x16/folder.png",
                icon_png_folder_16, icon_png_folder_16_LEN);
    fixture_png("data/icons/fdktest/16x16/text-x-generic.png",
                icon_png_text_16, icon_png_text_16_LEN);
    fixture_png("data/icons/fdktest/16x16/image-x-generic.png",
                icon_png_image_16, icon_png_image_16_LEN);
    fixture_png("data/icons/fdktest/16x16/run-symbolic.png",
                icon_png_exec_16, icon_png_exec_16_LEN);
    /* 48-px set. */
    fixture_png("data/icons/fdktest/48x48/folder.png",
                icon_png_folder_48, icon_png_folder_48_LEN);
    fixture_png("data/icons/fdktest/48x48/image-x-generic.png",
                icon_png_image_48, icon_png_image_48_LEN);
    /* The scalable dir serves any 16..64 request (audio). */
    fixture_png("data/icons/fdktest/32x32/audio-x-generic.png",
                icon_png_audio_16, icon_png_audio_16_LEN);
    /* scale!=1: present on disk, must never resolve. */
    fixture_png("data/icons/fdktest/64x64@2/video-x-generic.png",
                icon_png_video_48, icon_png_video_48_LEN);
    /* The threshold dir carries ONLY an SVG decoy for the zip name:
     * found on disk, never offered (PNG-only contract). */
    fixture_text("data/icons/fdktest/24x24/application-zip.svg",
                 "<svg xmlns=\"http://www.w3.org/2000/svg\"/>");
    /* The parent's 48-px archive chain member. */
    fixture_png("data/icons/fdkparent/48x48/package-x-generic.png",
                icon_png_archive_48, icon_png_archive_48_LEN);
    /* hicolor's terminal 16-px text icon. */
    fixture_png("data/icons/hicolor/16x16/text-x-generic.png",
                icon_png_text_16, icon_png_text_16_LEN);
    /* The pixmaps flat fallback (under the XDG_DATA_DIRS entry the
     * engine derives it from). */
    fixture_png("datadirs/pixmaps/fdk-legacy.png",
                icon_png_home_16, icon_png_home_16_LEN);
}

static void drop_fixture(void) {
    char buf[600];
    static const char *const files[] = {
        "data/icons/fdktest/16x16/folder.png",
        "data/icons/fdktest/16x16/text-x-generic.png",
        "data/icons/fdktest/16x16/image-x-generic.png",
        "data/icons/fdktest/16x16/run-symbolic.png",
        "data/icons/fdktest/48x48/folder.png",
        "data/icons/fdktest/48x48/image-x-generic.png",
        "data/icons/fdktest/32x32/audio-x-generic.png",
        "data/icons/fdktest/64x64@2/video-x-generic.png",
        "data/icons/fdktest/24x24/application-zip.svg",
        "data/icons/fdktest/24x24",
        "data/icons/fdktest/16x16",
        "data/icons/fdktest/32x32",
        "data/icons/fdktest/48x48",
        "data/icons/fdktest/64x64@2",
        "data/icons/fdktest/index.theme",
        "data/icons/fdktest",
        "data/icons/fdkparent/48x48/package-x-generic.png",
        "data/icons/fdkparent/48x48",
        "data/icons/fdkparent/index.theme",
        "data/icons/fdkparent",
        "data/icons/hicolor/16x16/text-x-generic.png",
        "data/icons/hicolor/16x16",
        "data/icons/hicolor/index.theme",
        "data/icons/hicolor",
        "data/icons",
        "data",
        "config",
        "datadirs/pixmaps/fdk-legacy.png",
        "datadirs/pixmaps",
        "datadirs",
        NULL,
    };
    for (int i = 0; files[i] != NULL; i++) {
        snprintf(buf, sizeof(buf), "%s/%s", g_root, files[i]);
        remove(buf);
    }
    remove(g_root);
}

/* ---- 1. name detection ---------------------------------------------- */

static void test_current_name(void) {
    env_point_at_fixture();

    /* The explicit override wins. */
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "env override detected");

    /* A hostile override is rejected and detection falls through. */
    setenv("FDK_ICON_THEME", "../../etc", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "hicolor") == 0,
          "hostile env name rejected -> default");

    /* The classic icon-theme file. */
    unsetenv("FDK_ICON_THEME");
    fixture_text("config/icon-theme", "fdktest\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "icon-theme file detected");

    /* GTK settings.ini (quoted value form). */
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/icon-theme", g_root);
        remove(buf);
    }
    fixture_dir("config/gtk-3.0");
    fixture_text("config/gtk-3.0/settings.ini",
                 "[Settings]\ngtk-icon-theme-name=\"fdktest\"\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "gtk-3.0 settings.ini detected (quoted)");

    /* kdeglobals. */
    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/gtk-3.0/settings.ini",
                 g_root);
        remove(buf);
    }
    fixture_text("config/kdeglobals",
                 "[Icons]\nTheme=fdktest\n");
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdktest") == 0,
          "kdeglobals [Icons] Theme detected");

    {
        char buf[600];
        snprintf(buf, sizeof(buf), "%s/config/kdeglobals", g_root);
        remove(buf);
    }
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "hicolor") == 0,
          "no statement anywhere -> hicolor");

    /* Detection re-reads after reset (no stale name across swaps). */
    setenv("FDK_ICON_THEME", "fdkparent", 1);
    fdk__icon_theme_reset();
    CHECK(strcmp(fdk__icon_theme_current_name(), "fdkparent") == 0,
          "name re-detected after reset");
    printf("[ok] icon theme: name detection chain "
           "(env > icon-theme > gtk ini > kdeglobals > hicolor; "
           "hostile names rejected)\n");
}

/* ---- 2. lookup ------------------------------------------------------- */

static void test_lookup(void) {
    env_point_at_fixture();
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();

    /* Exact size, own theme. */
    char *p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL && strstr(p, "fdktest/16x16/folder.png") != NULL,
          "exact-size own-theme hit");
    fdk_free(p);

    /* 48 serves from the 48 dir. */
    p = fdk__icon_theme_lookup("folder", 48);
    CHECK(p != NULL && strstr(p, "fdktest/48x48/folder.png") != NULL,
          "48-px hit");
    fdk_free(p);

    /* Scalable range: 20 fits 16..64 -> the 32x32 file. */
    p = fdk__icon_theme_lookup("audio-x-generic", 20);
    CHECK(p != NULL && strstr(p, "32x32/audio-x-generic.png") != NULL,
          "scalable dir serves in-range size");
    fdk_free(p);

    /* Relaxed pass: 64 is outside the theme's every dir for
     * image-x-generic except... 48 is closest -> the 48 file. */
    p = fdk__icon_theme_lookup("image-x-generic", 64);
    CHECK(p != NULL && strstr(p, "48x48/image-x-generic.png") != NULL,
          "relaxed closest-size fallback");
    fdk_free(p);

    /* Inheritance: archive names miss fdktest (SVG decoy never
     * offered) -> the parent's package-x-generic. */
    p = fdk__icon_theme_lookup("package-x-generic", 48);
    CHECK(p != NULL && strstr(p, "fdkparent/48x48") != NULL,
          "inherited hit from parent theme");
    fdk_free(p);

    /* The hicolor terminal. */
    p = fdk__icon_theme_lookup("nothing-anywhere", 16);
    CHECK(p == NULL, "unknown name misses everywhere");
    /* Negative result cached: still NULL, no filesystem churn. */
    p = fdk__icon_theme_lookup("nothing-anywhere", 16);
    CHECK(p == NULL, "negative cache hit");

    /* SVG is never offered even though the file exists. */
    p = fdk__icon_theme_lookup("application-zip", 24);
    CHECK(p == NULL, "SVG decoy never offered (PNG-only)");

    /* scale != 1 directories are skipped. */
    p = fdk__icon_theme_lookup("video-x-generic", 64);
    CHECK(p == NULL, "scale!=1 dir skipped");

    /* Threshold: 22 within 24+-2 -> the dir serves... but the only
     * file in it is the SVG decoy -> miss (honest). */
    p = fdk__icon_theme_lookup("archive-x-generic", 22);
    CHECK(p == NULL, "threshold dir with only SVG misses");

    /* The pixmaps flat fallback. */
    p = fdk__icon_theme_lookup("fdk-legacy", 16);
    CHECK(p != NULL && strstr(p, "pixmaps/fdk-legacy.png") != NULL,
          "pixmaps flat fallback");
    fdk_free(p);

    /* Hostile icon names never reach the filesystem. */
    CHECK(fdk__icon_theme_lookup("../..", 16) == NULL,
          "hostile icon name rejected");
    CHECK(fdk__icon_theme_lookup("a/b", 16) == NULL,
          "icon name with slash rejected");

    printf("[ok] icon theme: lookup (exact, scalable, relaxed, "
           "inheritance, hicolor terminal, SVG/scale skips, pixmaps, "
           "negative cache, path safety)\n");
}

/* ---- 3. reset drops the caches --------------------------------------- */

static void test_reset(void) {
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();
    char *p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL, "pre-reset lookup");
    fdk_free(p);

    /* Break the fixture, reset, and confirm the miss is fresh. Both
     * the 16 and the 48 file must go: the relaxed pass would
     * otherwise LEGITIMATELY serve the 48-px icon at distance 32. */
    char buf[600];
    snprintf(buf, sizeof(buf), "%s/data/icons/fdktest/16x16/folder.png",
             g_root);
    remove(buf);
    snprintf(buf, sizeof(buf), "%s/data/icons/fdktest/48x48/folder.png",
             g_root);
    remove(buf);
    fdk__icon_theme_reset();
    p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p == NULL, "reset drops positive cache (miss is fresh)");
    fdk_free(p);

    /* Negative cache drops too: restore + reset -> hit again. */
    fixture_png("data/icons/fdktest/16x16/folder.png",
                icon_png_folder_16, icon_png_folder_16_LEN);
    fixture_png("data/icons/fdktest/48x48/folder.png",
                icon_png_folder_48, icon_png_folder_48_LEN);
    fdk__icon_theme_reset();
    p = fdk__icon_theme_lookup("folder", 16);
    CHECK(p != NULL, "reset drops negative cache");
    fdk_free(p);
    printf("[ok] icon theme: reset drops positive and negative caches\n");
}

/* ---- 4. surfaces + symbolic tint ------------------------------------- */

static void test_surfaces(void) {
    setenv("FDK_ICON_THEME", "fdktest", 1);
    fdk__icon_theme_reset();

    /* Decode + identity: the folder icon is pure blue. */
    fdk_surface *s = fdk__icon_theme_surface("folder", 16);
    CHECK(s != NULL, "surface decodes");
    fdk_surface_info info;
    CHECK(fdk_surface_get_info(s, &info) == FDK_OK, "surface info");
    CHECK(info.width == 16 && info.height == 16, "16-px icon decoded");
    fdk_u32 px = info.pixels[0];
    CHECK((px >> 24 & 0xFFu) == 0xFFu && (px >> 16 & 0xFFu) == 0x00u &&
          (px >> 8 & 0xFFu) == 0x00u && (px & 0xFFu) == 0xFFu,
          "folder icon is solid blue (identity by color)");

    /* The borrow contract: same pointer for the same (name,size). */
    fdk_surface *again = fdk__icon_theme_surface("folder", 16);
    CHECK(again == s, "surface cache returns the same borrow");

    /* Different size, different surface. */
    fdk_surface *big = fdk__icon_theme_surface("folder", 48);
    CHECK(big != NULL && big != s, "48-px is its own surface");
    CHECK(fdk_surface_get_info(big, &info) == FDK_OK &&
          info.width == 48, "48-px decoded");

    /* The symbolic tint: run-symbolic's magenta is replaced by the
     * theme's text ink, alpha preserved. */
    fdk_surface *sym = fdk__icon_theme_surface("run-symbolic", 16);
    CHECK(sym != NULL, "symbolic surface decodes");
    CHECK(fdk_surface_get_info(sym, &info) == FDK_OK, "symbolic info");
    fdk_color ink = fdk_theme_get_color(NULL, FDK_TK_TEXT);
    px = info.pixels[0];
    fdk_u32 want_r = (fdk_u32)(ink.r * 255.0f + 0.5f);
    fdk_u32 want_g = (fdk_u32)(ink.g * 255.0f + 0.5f);
    fdk_u32 want_b = (fdk_u32)(ink.b * 255.0f + 0.5f);
    CHECK((px >> 24 & 0xFFu) == 0xFFu &&
          (px >> 16 & 0xFFu) == want_r && (px >> 8 & 0xFFu) == want_g &&
          (px & 0xFFu) == want_b,
          "symbolic icon tinted with the theme's text ink");

    /* The chain resolver: first decodable entry wins; a fully
     * missing chain misses. */
    static const char *const chain_hit[] = { "no-such-icon",
                                             "folder", NULL };
    CHECK(fdk__icon_theme_surface_chain(chain_hit, 16) == s,
          "chain resolver skips misses to the first hit");
    static const char *const chain_miss[] = { "no-such-icon", NULL };
    CHECK(fdk__icon_theme_surface_chain(chain_miss, 16) == NULL,
          "all-miss chain returns NULL");

    /* Reset destroys the surfaces (the fresh decode proves it). */
    fdk__icon_theme_reset();
    fdk_surface *fresh = fdk__icon_theme_surface("folder", 16);
    CHECK(fresh != NULL && fresh != s,
          "reset drops decoded surfaces (new pointer)");
    printf("[ok] icon theme: surfaces (decode, borrow identity, "
           "symbolic tint pixels, chain resolution, reset)\n");
}

/* ---- 5. classification ----------------------------------------------- */

static void test_classification(void) {
    /* Directories are folders, case does not matter, and the
     * executable bit splits extension-less files. */
    CHECK(fdk__icon_chain_for_entry("/x", "anything", true) != NULL &&
          strcmp(fdk__icon_chain_for_entry("/x", "anything", true)[0],
                 "folder") == 0,
          "directory classifies as folder");

    const char *const *c =
        fdk__icon_chain_for_entry("/x", "photo.PNG", false);
    CHECK(c != NULL && strcmp(c[0], "image-x-generic") == 0,
          "extension match is case-insensitive");

    c = fdk__icon_chain_for_entry("/x", "archive.tar.gz", false);
    CHECK(c != NULL && strcmp(c[0], "application-x-compressed-tar") == 0,
          "compound extension classified");

    c = fdk__icon_chain_for_entry("/x", "main.c", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-csrc") == 0,
          "source file classified");

    c = fdk__icon_chain_for_name("song.opus");
    CHECK(c != NULL && strcmp(c[0], "audio-x-generic") == 0,
          "audio classified");

    c = fdk__icon_chain_for_name("movie.mkv");
    CHECK(c != NULL && strcmp(c[0], "video-x-generic") == 0,
          "video classified");

    /* Extension-less files: the executable bit decides. */
    char dir[700];
    snprintf(dir, sizeof(dir), "%s/cls", g_root);
    mkdir(dir, 0755);
    char prog[768], plain[768];
    snprintf(prog, sizeof(prog), "%s/runme", dir);
    snprintf(plain, sizeof(plain), "%s/plainfile", dir);
    write_file(prog, "#!/bin/sh\n", 10);
    write_file(plain, "data", 4);
    chmod(prog, 0755);

    c = fdk__icon_chain_for_entry(dir, "runme", false);
    CHECK(c != NULL && strcmp(c[0], "application-x-executable") == 0,
          "extension-less + exec bit -> executable chain");
    c = fdk__icon_chain_for_entry(dir, "plainfile", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-generic") == 0,
          "extension-less plain file -> text chain");

    /* Unknown extensions fall to the exec-bit split too. */
    c = fdk__icon_chain_for_entry(dir, "data.zzz", false);
    CHECK(c != NULL && strcmp(c[0], "text-x-generic") == 0,
          "unknown extension -> exec-bit split -> text");

    /* Every chain is NULL-terminated (the resolver walks safely). */
    for (size_t i = 0; i < 32; i++) {
        char name[32];
        snprintf(name, sizeof(name), "f%zu.zzz", i);
        const char *const *ch = fdk__icon_chain_for_entry(dir, name,
                                                          false);
        CHECK(ch != NULL && ch[0] != NULL, "chains always non-empty");
    }

    /* The place chains carry the symbolic-first desktop norm. */
    CHECK(strcmp(fdk__icon_chain_place(FDK_ICON_PLACE_HOME)[0],
                 "user-home-symbolic") == 0,
          "home place chain is symbolic-first");
    CHECK(strcmp(fdk__icon_chain_place(FDK_ICON_PLACE_DRIVE)[0],
                 "drive-harddisk-symbolic") == 0,
          "drive place chain is symbolic-first");

    remove(prog);
    remove(plain);
    remove(dir);
    printf("[ok] icon theme: classification (case-insensitive exts, "
           "compound exts, exec-bit split, place chains)\n");
}

int main(void) {
    build_fixture();
    test_current_name();
    test_lookup();
    test_reset();
    test_surfaces();
    test_classification();
    drop_fixture();
    if (failures == 0) {
        printf("all icon-theme tests passed\n");
        return 0;
    }
    fprintf(stderr, "%d icon-theme test failure%s\n", failures,
            failures == 1 ? "" : "s");
    return 1;
}
